"""Concise outcome report, built only after independent completed-test checks."""
from common import *

def resources():
 result={}
 for folder in (CACHE/'runs').iterdir():
  if not folder.is_dir() or not(folder/'telemetry.jsonl').exists():continue
  telemetry=rows(folder/'telemetry.jsonl');exit=read(folder/'exit.json') if (folder/'exit.json').exists() else {'status':'running'}
  result[folder.name]={'exit':exit,'peak_gpu_mib':max(x['gpu_mib'] for x in telemetry),'min_host_available_bytes':min(x['host_available'] for x in telemetry),'peak_host_used_bytes':max(x['host_used'] for x in telemetry),'peak_gpu_temperature_c':max(x['gpu_temp_c'] for x in telemetry),'swap_in_bytes':max(x['swap_in_delta'] for x in telemetry),'swap_out_bytes':max(x['swap_out_delta'] for x in telemetry)}
  disk=[x['disk_free_bytes'] for x in telemetry if 'disk_free_bytes' in x]
  if disk:result[folder.name]['minimum_disk_free_bytes']=min(disk);result[folder.name]['observed_disk_growth_bytes']=max(0,disk[0]-min(disk))
 save(STUDY/'results/resources.json',result);return result

def main():
 validation=read(STUDY/'results/independent_verification.json');assert validation['status']=='passed';lock=read(STUDY/'FINAL_EVAL_LOCK.json');assert lock['locked'];comp=read(STUDY/'results/paired_final_comparisons.json');stats=resources();q=read(STUDY/'results/query/confirmation.json');rr=read(STUDY/'results/reranker/SELECTION_LOCK.json');metrics={p.name[:-13]:read(p)['aggregate'] for p in (STUDY/'results/final').glob('*.metrics.json')};assert all(name in metrics for name in ['reconstructed-base','adapted-query','released-reranker','trained-reranker']);primary=lock['primary_condition'];effect=comp[primary];win=effect['ndcg10_delta']>0 and effect['ci95'][0]>0;training=comp.get('local-reranker-training-effect');maxgpu=max(x['peak_gpu_mib'] for x in stats.values());minram=min(x['min_host_available_bytes'] for x in stats.values());lat=read(STUDY/'results/latency-end-to-end20.json')
 metrics={'archived-base':read(STUDY/'results/archived_baseline_verification.json')['evaluation']['aggregate'],**dict(sorted(metrics.items()))}
 text=['# Local SkillRet challenger results','',f'The locked primary challenger **{primary}** achieved **{metrics[primary]["NDCG@10"]:.6f} NDCG@10** versus **0.810990** for the archived full-text SkillRet-Embedding-0.6B reference. Its paired difference is **{effect["ndcg10_delta"]*100:+.3f} percentage points**, with a 95% question-bootstrap interval **[{effect["ci95"][0]*100:+.3f}, {effect["ci95"][1]*100:+.3f}]**. '+('This meets the declared point-and-interval criterion.' if win else 'This does not meet the declared point-and-interval criterion.'),'','All conditions retain 4,392 official queries, all 6,006 skills and 7,187 exact-ID positives. Missing/failed results remain in the denominator. The original 32K representation, including two truncated test documents, is preserved. The absent original WSL index was reconstructed once and checked against every archived top50 ranking.','', '| Condition | NDCG@10 | Recall@10 | MRR@10 | Completeness@10 |','|---|---:|---:|---:|---:|']
 for name,m in metrics.items():text.append(f'| {name} | {m["NDCG@10"]:.6f} | {m["Recall@10"]:.6f} | {m["MRR@10"]:.6f} | {m["Completeness@10"]:.6f} |')
 original=metrics['archived-base'];chosen=metrics[primary];counts=read(STUDY/'results/final_status_counts.json')[primary];parity=read(STUDY/'results/reconstruction_diagnostics.json')
 text+=['',f'The primary changed Recall@10 by {(chosen["Recall@10"]-original["Recall@10"])*100:+.3f} points and Completeness@10 by {(chosen["Completeness@10"]-original["Completeness@10"])*100:+.3f} points versus the archive. It recorded {counts["failed_inference"]} inference failures, {counts["no_record"]} missing records and {counts["successful_retrieval_miss_at50"]} successful requests without a known relevant result in the top 50.','',f'The reconstruction matched {parity["identical_top50_count"]:,}/4,392 archived top-50 rankings exactly and {parity["identical_top10_count"]:,}/4,392 top-10 rankings. Its NDCG@10 differed by {parity["reconstructed_minus_archived_ndcg10"]*100:+.5f} points. See the [ranking comparison](results/reconstruction_diagnostics.json).']
 text+=['','The full metric table includes NDCG@5/10/15, Recall@5/10/20/50, MRR@5/10, MAP@5/10, Precision@5/10 and Completeness@5/10. Hit@1 and multi-positive Recall@1 are distinct. See [metrics](results/final_metrics.csv) and [paired results](results/paired_final_comparisons.json).','',f'Query-only confirmation changed NDCG@10 by {q["delta"]*100:+.3f} points on its independent 512-query training-origin panel. The selected mixture weight was {lock["query"]["mixture_weight"]}; document vectors never change. Weight zero is the real frozen baseline. Fractional mixing requires two query encodings.','']
 qe=comp['query-training-vs-reconstructed-start'];text.append(f'The pure query adapter changed official NDCG@10 versus the reconstructed unadapted encoder by {qe["ndcg10_delta"]*100:+.3f} points (paired interval [{qe["ci95"][0]*100:+.3f}, {qe["ci95"][1]*100:+.3f}]). This comparison uses the identical frozen document index and no reranking.')
 if 'query-mixture-vs-reconstructed-start' in comp:
  e=comp['query-mixture-vs-reconstructed-start'];text.append(f'The fixed query mixture changed NDCG@10 by {e["ndcg10_delta"]*100:+.3f} points versus that same unadapted encoder (paired interval [{e["ci95"][0]*100:+.3f}, {e["ci95"][1]*100:+.3f}]).')
 secondary=lock['secondary_query'];step=secondary['best_step'];secondary_result=read(STUDY/f'results/query/{secondary["trial"]}/selection-{step:05d}.json')
 from analyze import paired
 selected_weight=f'{secondary["mixture_weight"]:g}';secondary_ev=secondary_result['mixtures'][selected_weight]
 secondary_effect=paired(secondary_result['mixtures']['0'],secondary_ev)
 text.append(f'The query repeat used seed 43, the same checkpoint depth ({step} updates) and the fixed {selected_weight} mixture. On training-origin selection it scored {secondary_ev["aggregate"]["NDCG@10"]:.6f} versus {secondary_result["mixtures"]["0"]["aggregate"]["NDCG@10"]:.6f} frozen ({secondary_effect["ndcg10_delta"]*100:+.3f} points, descriptive interval [{secondary_effect["ci95"][0]*100:+.3f}, {secondary_effect["ci95"][1]*100:+.3f}]). This repeat did not choose a new configuration.')
 if 'released-fusion-effect' in comp:
  e=comp['released-fusion-effect'];text.append(f'With the released reranker and the same candidate pool, the fixed learned fusion changed NDCG@10 versus unfused reranking by {e["ndcg10_delta"]*100:+.3f} points (paired interval [{e["ci95"][0]*100:+.3f}, {e["ci95"][1]*100:+.3f}]). This isolates the fusion choice from a change in model weights.')
 if training:text.append(f'At identical candidate/input/fusion settings, local reranker training changed official NDCG@10 versus its own unchanged released starting checkpoint by {training["ndcg10_delta"]*100:+.3f} points, with interval [{training["ci95"][0]*100:+.3f}, {training["ci95"][1]*100:+.3f}]. A released-reranker advantage is not attributed to our updates.')
 if 'local-reranker-training-unfused' in comp:
  e=comp['local-reranker-training-unfused'];text.append(f'Without dense-score fusion, the same local reranker training changed NDCG@10 by {e["ndcg10_delta"]*100:+.3f} points (paired interval [{e["ci95"][0]*100:+.3f}, {e["ci95"][1]*100:+.3f}]).')
 for name,label in [('local-reranker-training-in-combined','With the same adapted-query candidate pools, training the reranker'),('query-training-in-reranker-pipeline','With the same trained reranker, adapting the query encoder')]:
  if name in comp:
   e=comp[name];text.append(f'{label} changed NDCG@10 by {e["ndcg10_delta"]*100:+.3f} points (paired interval [{e["ci95"][0]*100:+.3f}, {e["ci95"][1]*100:+.3f}]).')
 policies=read(STUDY/'results/reranker/policy_selection.json');selected_policy=policies['selected'];full_policy=policies['full_coverage_candidate']
 text+=['',f'The released development control used {selected_policy["budget"]:,} input tokens, top {selected_policy["candidates"]} candidates and reranker weight {selected_policy["fusion_weight"]}. The complete-window alternative scored {full_policy["ndcg10"]:.6f} NDCG@10 at {policies["full_vs_selected_median_rerank_time_ratio"]:.2f}× the selected-evidence median time before the full-coverage promotion decision. It {"met" if policies["full_coverage_promoted"] else "did not meet"} the preregistered joint quality and time criterion.']
 pilot=read(STUDY/'results/reranker/pilot_matched_comparison.json');effect_trained=pilot['training_effect_at_trained_policy'];effect_released=pilot['training_effect_at_released_policy']
 text.append(f'The 100-update pilot scored {pilot["trained_selected_ndcg10"]:.6f} on selection versus {pilot["released_selected_ndcg10"]:.6f} for the released model’s best policy. At the trained policy’s fixed fusion, the weight update changed NDCG@10 by {effect_trained["delta_ndcg10"]*100:+.3f} points; at the released policy’s fixed fusion it changed by {effect_released["delta_ndcg10"]*100:+.3f} points. See [the matched pilot audit](results/reranker/pilot_matched_comparison.json) for the descriptive intervals.')
 budgets=STUDY/'results/reranker/selected_evidence_comparison.json'
 if budgets.exists():
  dev=read(budgets);x=dev['descriptive_best_budget_contrast'];t=dev['render_and_score_seconds']
  text.append(f'On selection, the best released 2,048-token policy gained {x["delta_ndcg10"]*100:+.3f} points over the best 1,024-token policy (descriptive paired interval [{x["paired_95_percentile_interval"][0]*100:+.3f}, {x["paired_95_percentile_interval"][1]*100:+.3f}]); median rendering and scoring were {t["2048-top50"]["median"]:.2f}s and {t["1024-top20"]["median"]:.2f}s, respectively. These policy choices share the selection panel, so the interval does not account for choosing the policies.')
 text+=['',f'Peak whole-device use across this campaign was {maxgpu:,} MiB; minimum host available memory was {minram/1024**3:.2f} GiB. Per-phase runtime, temperature, swap counters, training step coverage and source receipts are retained. All training, mining and scoring ran locally on the verified i3-3225 / RTX2060SUPER8GB server. No external teacher or GPU service was used.','',f'Actual uncached one-model deployment latency on the fixed 20-query sample was median {lat["median_seconds"]:.3f}s and p95 {lat["p95_seconds"]:.3f}s, with the model residency and startup boundary recorded in the latency receipt. This is separate from full-test component timings and cannot be interpreted as a free speedup. Indexing and training are one-time costs.','', 'Evidence reranking retains the complete query and required scoring suffix, but selects bounded body spans from the original full SKILL.md; it does not claim complete source coverage. The full-window development alternative and its measured costs are saved separately. Incomplete judgments may leave unjudged relevant negatives.','', 'Development skills are held out from our updates, not necessarily from released-checkpoint pretraining. The original official train/test partitions share 1,054 source repositories, despite no shared exact skill IDs, source URLs or normalized body hashes. The official test is historically exposed. Other than the locked primary contrast, comparisons are secondary and have no multiplicity correction. The bootstrap interval conditions on fixed selected recipes and observed queries; it does not capture all seed, checkpoint-selection, pretraining or dataset-exposure uncertainty. Validation differences and training changes do not isolate a unique cause of success or failure.','', 'The earlier failed BGE study is unchanged. This campaign does not establish document length as its sole failure mechanism. No official final scores were used to retune this campaign.','', 'Base weights remain outside Git. Portable query/reranker best/final adapters and lossless normalized document/query vectors are published through Git LFS. The query adapter must remain query-only; never merge it into the document encoder. Reproduction code, source pins, the evaluation lock, per-query records and independent checks accompany the artifacts.']
 timing=read(STUDY/'results/timing_components.json');base_times=timing['reconstructed-base']['seconds'];primary_times=timing[primary]['seconds'];qtrial=read(STUDY/f'results/query/{lock["query"]["trial"]}/summary.json');rtrial=read(STUDY/f'results/reranker/{lock["reranker"]["trial"]}/summary.json');di=read(CACHE/'vectors/train-documents/complete.json');ti=read(CACHE/'vectors/test-documents/complete.json');qa=read(CACHE/'vectors/train-queries/complete.json');promotion=lock['development_promotion']
 r_optimizer_seconds=sum(x["seconds"] for x in rows(STUDY/f'results/reranker/{lock["reranker"]["trial"]}/steps.jsonl'))
 baseline_latency=read(STUDY/'results/latency-end-to-end20-frozen.json');text+=['',f'On the same uncached 20-query sample, the frozen baseline took {baseline_latency["median_seconds"]:.3f}s median and {baseline_latency["p95_seconds"]:.3f}s p95 with its single encoder resident.']
 deployment_latency=STUDY/'results/latency-end-to-end20-deployment.json'
 if deployment_latency.exists():
  measured=read(deployment_latency);text.append(f'The separate development-recommended deployment, {measured["condition"]}, took {measured["median_seconds"]:.3f}s median and {measured["p95_seconds"]:.3f}s p95 on that same sample.')
 text+=['',f'The selected query trial ran {qtrial["steps"]} optimizer attempts over {qtrial["unique_query_count"]:,} distinct training queries, with {qtrial["training_wall_seconds"]/60:.2f} minutes of training and validation; the selected query checkpoint was step {lock["query"]["best_step"]}. The selected reranker trial ran {rtrial["steps"]} attempts over {rtrial["pairs"]:,} pairs from {rtrial["unique_query_count"]:,} queries in {rtrial["training_wall_seconds"]/60:.2f} minutes including validation ({r_optimizer_seconds/60:.2f} active optimizer minutes); the selected reranker checkpoint was step {lock["reranker"]["best_step"]}. See `results/resources.json` for all trials, repeated seeds and discarded fixtures.','',f'One-time active encoding was {di["active_seconds"]/60:.2f} minutes for the frozen training document index, {qa["active_seconds"]/60:.2f} minutes for its query anchors and {ti["active_seconds"]/60:.2f} minutes for the reconstructed test document index. These times exclude cache writes and model startup.','',f'On the full test, the frozen encoder had an active component sum of median {base_times["active_component_sum"]["median"]*1000:.2f} ms / p95 {base_times["active_component_sum"]["p95"]*1000:.2f} ms. The locked primary was median {primary_times["active_component_sum"]["median"]*1000:.2f} ms / p95 {primary_times["active_component_sum"]["p95"]*1000:.2f} ms. Component sums exclude model loading/switching; the separate actual deployment sample measures its stated residency boundary. See `results/timing_components.json` for encode, search, window selection and reranking separately.','',f'Development-only deployment gate: **{promotion["deployment_condition"]}**. The candidate was **{promotion["selection_candidate"]}**; the independent confirmation NDCG@10 difference was {promotion["confirmation_delta"]*100:+.3f} points with interval [{promotion["paired_ci95"][0]*100:+.3f}, {promotion["paired_ci95"][1]*100:+.3f}]. Official results did not change this choice.']
 reuse=timing[primary].get('offline_score_reuse')
 if reuse:
  text+=['',f'The primary’s full-test component sum is offline execution work: it reused {reuse["reused"]:,} scores from the identical checkpoint, input tokens and padded tensor shape and computed {reuse["fresh_inputs"]:,} fresh scores. The same independent uncached sample is the deployment comparison. The development parity gate, official direct-execution audits and full saved-score verification are retained.']
 scaling=read(STUDY/'results/scaling.json');scope=lock['scaling'];sizes=scope['library_sizes']
 assert len(scaling)==len(sizes)*(len(scope['dense_conditions'])+len(scope['reranker_conditions']))
 text+=['',f'The exposed scaling panel tested {len(scaling)//len(sizes)} conditions on the same 20 historical questions across all eight exact saved pools. It includes the locked challenger and its matched released control when the primary is combined. See [the scaling plot](figures/04-scaling.png) and [the full panel results](results/scaling.json). Pool membership varies with size, so the curve is secondary evidence.']
 (STUDY/'REPORT.md').write_text('\n'.join(text)+'\n');print('Report built',primary,win,flush=True)
if __name__=='__main__':main()
